// === Jarvis "leader -> branch" bot: robot error/alarm + symbol glossary ===
const REG_URL = "https://raw.githubusercontent.com/ntvn2022/z-bee-duo/claude/esp32-s3-touch-screen-wwelt1/xiaozhi-ai/machines/registry.json";
const body = ($input.first().json.body) || $input.first().json || {};
const text = (body.text || "").toString().trim();
const MODEL = body.model || "gemini-2.5-flash";
const GEMINI_KEY = body.gemini_key || $env.GEMINI_API_KEY || "";
const out = (o) => [{ json: o }];
if (!text) return out({ reply: "Bạn muốn hỏi lỗi/cảnh báo hay ký hiệu của máy nào?", need: "text" });
if (/(k[eế]t th[uú]c robot|tho[aá]t robot|d[uừ]ng robot)/i.test(text))
  return out({ reply: "Đã thoát chế độ tra cứu lỗi máy.", mode: "exit" });

const norm = (s) => (s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");
const t = norm(text);
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
const clean = (s) => (s||"").replace(/[*#]/g,"").replace(/\s*\n\s*/g," ").replace(/\s{2,}/g," ").trim();
const GURL = `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${GEMINI_KEY}`;

// 1) LEADER: machine by last-mentioned alias
const registry = await this.helpers.httpRequest({ url: REG_URL, json: true });
let machine=null, best=-1;
for (const m of registry) for (const a of (m.aliases||[])) {
  const p=t.lastIndexOf(norm(a)); if(p>best){best=p;machine=m;}
}
if(!machine){ if(registry.length===1) machine=registry[0];
  else return out({reply:"Bạn hỏi về máy nào? Hiện có: "+registry.map(m=>m.name_vi).join(", ")+".",need:"machine"}); }

const rows = await this.helpers.httpRequest({ url: machine.tables_url, json: true });

// 2) SYMBOL lookup first (T23, X03, Y17, RY3, FCW...). Only symbols with a DIGIT or starting FC
//    (avoid clashing with Vietnamese words like "mã" -> "ma").
let sym=null, sp=-1;
for(const r of rows){
  if(r.type!=="symbol") continue;
  const c=r.code; if(!(/\d/.test(c) || /^FC/i.test(c))) continue;
  const p=t.search(new RegExp("\\b"+esc(c.toLowerCase())+"\\b"));
  if(p>=0 && p>sp){ sp=p; sym=r; }
}
if(sym){
  let reply="";
  if(GEMINI_KEY){ try{
    const g=await this.helpers.httpRequest({method:"POST",url:GURL,json:true,body:{contents:[{parts:[{text:
      `Người dùng hỏi ý nghĩa ký hiệu "${sym.code}" trên ${machine.name_vi}. Giải thích NGẮN GỌN, dễ hiểu, bằng tiếng Việt, văn xuôi trơn, không markdown, không ký hiệu * #. CHỈ dựa vào dữ liệu: ${sym.code} = ${sym.content}\n\nCâu hỏi: ${text}`
    }]}]}});
    reply=clean(g?.candidates?.[0]?.content?.parts?.[0]?.text||"");
  }catch(e){ reply=""; } }
  if(!reply) reply=`${sym.code}: ${clean(sym.content)}`;
  return out({ reply, machine:machine.id, symbol:sym.code, kind:"symbol" });
}

// 3) ERROR/ALARM by last number
const nums=t.match(/\d{1,3}/g);
if(!nums) return out({reply:`Bạn hỏi mã lỗi (error) / cảnh báo (alarm) số mấy, hay ký hiệu nào của ${machine.name_vi}?`,need:"code"});
const num=parseInt(nums[nums.length-1],10);
const ia=Math.max(t.lastIndexOf("alarm"),t.lastIndexOf("canh bao"));
const ie=Math.max(t.lastIndexOf("error"),t.lastIndexOf("loi"));
const wantAlarm=ia>=0&&ia>ie, wantError=ie>=0&&ie>ia;
const matches=rows.filter(r=>r.type!=="symbol" && parseInt(r.code,10)===num);
if(!matches.length) return out({reply:`Không thấy mã ${num} cho ${machine.name_vi}. Bạn kiểm tra lại số giúp mình nhé.`,need:"code"});
const errT=machine.error_types||[], almT=machine.alarm_types||[];
const grp=(ty)=>errT.includes(ty)?"error":(almT.includes(ty)?"alarm":"other");
const hasErr=matches.some(m=>grp(m.type)==="error"), hasAlm=matches.some(m=>grp(m.type)==="alarm");
let selected=matches, askType=false;
if(wantError&&!wantAlarm) selected=matches.filter(m=>grp(m.type)==="error");
else if(wantAlarm&&!wantError) selected=matches.filter(m=>grp(m.type)==="alarm");
else if(hasErr&&hasAlm) askType=true;
if(!selected.length) selected=matches;
const ctx=selected.map(m=>`[${m.type} ${m.code}] ${m.content}`).join("\n");
let s=`Bạn là trợ lý kỹ thuật cho ${machine.name_vi}. Trả lời bằng ngôn ngữ người hỏi (mặc định tiếng Việt), NGẮN GỌN, đúng thứ tự: mô tả lỗi; nguyên nhân; cách khắc phục. Viết văn xuôi TRƠN, KHÔNG markdown, KHÔNG ký hiệu * # hay đánh số. `;
if(askType) s+=`Mã ${num} có ở CẢ cảnh báo (alarm) LẪN lỗi (error) — tóm tắt cả hai loại rồi hỏi lại người dùng muốn loại nào. `;
s+=`Kết thúc luôn kèm câu nhắc: cần phân biệt cảnh báo (alarm) và lỗi (error) vì là hai khái niệm khác nhau. CHỈ dùng dữ liệu sau:\n${ctx}`;
let reply="";
if(GEMINI_KEY){ try{
  const g=await this.helpers.httpRequest({method:"POST",url:GURL,json:true,body:{contents:[{parts:[{text:s+`\n\nCâu hỏi: ${text}`}]}]}});
  reply=clean(g?.candidates?.[0]?.content?.parts?.[0]?.text||"");
}catch(e){ reply=""; } }
if(!reply) reply=selected.map(m=>`${m.type} ${m.code}: ${m.content}`).join("  |  ")+"  (Lưu ý: cảnh báo/alarm và lỗi/error khác nhau.)";
return out({ reply, machine:machine.id, code:num, types:selected.map(m=>m.type), askType });
